INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "成汭许存溯江，取滨江州县", "start_year": 896, "end_year": 896, "time_original": "896年五月条；确日未载", "dynasty": "唐", "description": "荆南节度使成汭与其将许存溯江略地，取滨江州县。", "phases": [], "location_name": "滨江州县", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4a832591-d400-5a79-afc6-298b59409581"}, {"title": "王建肇弃黔州，收余众保丰都", "start_year": 896, "end_year": 896, "time_original": "896年成汭许存略地条；确日未载", "dynasty": "唐", "description": "武泰节度使王建肇放弃黔州，收集余众，退保丰都。", "phases": [], "location_name": "黔州、丰都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8a331f54-b3fc-5b98-be27-ef847e8ccc4f"}, {"title": "许存引兵西取谕、涪二州", "start_year": 896, "end_year": 896, "time_original": "896年溯江略地后条；确日未载", "dynasty": "唐", "description": "许存又率兵向西，攻取底本所记“谕、涪二州”；“谕”与补书“渝”存在字形差异。", "phases": [], "location_name": "谕、涪二州（底本）", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f65adf15-a62a-5f39-9d66-8a0848def77e"}, {"title": "成汭任赵武黔中留后、许存万州刺史", "start_year": 896, "end_year": 896, "time_original": "896年取二州以后；确日未载", "dynasty": "唐", "description": "成汭任其将赵武为黔中留后，许存为万州刺史。", "phases": [], "location_name": "黔中、万州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "468017f5-5cc1-5775-9662-553870cc0c80"}, {"title": "成汭使人探察许存，获不治州事蹴鞠报告", "start_year": 896, "end_year": 896, "time_original": "896年许存任万州刺史后条；确日未载", "dynasty": "唐", "description": "成汭得知许存不得志，派人探察，获报告称许存不处理州务，每天出外蹴鞠。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "93a9729f-7496-531b-8a65-673141b30d96"}, {"title": "成汭认为许存蹴鞠是在准备逃跑", "start_year": 896, "end_year": 896, "time_original": "896年接探察报告后；确日未载", "dynasty": "唐", "description": "成汭认为许存将要逃走，蹴鞠是在先练足力。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "d6b3e0b0-4741-52a0-921d-6101b122180c"}, {"title": "成汭遣兵袭许存，许存弃城逃屯茅坝", "start_year": 896, "end_year": 896, "time_original": "896年探察及猜测后条；确日未载", "dynasty": "唐", "description": "成汭派兵袭击许存，许存弃城逃走，其部众逐渐归来，屯驻茅坝。", "phases": [], "location_name": "茅坝", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "557d4935-bd48-5c46-833d-1b7a08c712c3"}, {"title": "赵武攻丰都，王建肇许存降王建", "start_year": 896, "end_year": 896, "time_original": "896年茅坝屯驻以后条；数攻及请降确日未载", "dynasty": "唐", "description": "赵武多次攻丰都，王建肇无法继续守城，与许存都投降王建。", "phases": [], "location_name": "丰都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "05cc25c8-ccf1-591b-a750-93ba5bcda90d"}, {"title": "王建忌许存欲杀，高烛谏阻", "start_year": 896, "end_year": 896, "time_original": "896年许存归降后条；确日未载", "dynasty": "唐", "description": "王建忌许存勇略，想杀他；掌书记高烛以许存穷困来归、王建应招揽英雄为由劝阻。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "3f0deeab-be98-5c21-bc42-8fbdf9ed361e"}, {"title": "王建遣许存戍蜀州，密命王宗绾察之", "start_year": 896, "end_year": 896, "time_original": "896年高烛劝阻后条；确日未载", "dynasty": "唐", "description": "王建令许存守蜀州，又秘密令知蜀州王宗绾观察他。", "phases": [], "location_name": "蜀州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "cfc6a3d0-f366-5beb-8767-aaa12f215ac4"}, {"title": "王宗绾密言许存良将才，王建舍之改名王宗播", "start_year": 896, "end_year": 896, "time_original": "896年蜀州观察后条；确日未载", "dynasty": "唐", "description": "王宗绾密报许存忠勇廉厚、有良将才能，王建放弃杀他，改其姓名为王宗播。王宗绾始终未使他知自己曾助其免死。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "169300de-50f1-5000-91cc-9aded4b685b3"}, {"title": "柳修业常劝王宗播慎静免祸", "start_year": null, "end_year": null, "time_original": "卷260乾宁三年条内往事及常行概述；起讫未载", "dynasty": "唐", "description": "柳修业多次劝王宗播谨慎安静，以免招祸。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "fe2cec0f-f793-5ac5-acb3-ffe3d278e795"}, {"title": "王宗播后来先身战强敌，有功称病不自伐", "start_year": null, "end_year": null, "time_original": "其后概述；战事和终身起讫未载", "dynasty": "唐", "description": "主书概述王宗播后来为王建将，遇其他将领畏惧的强敌常亲自争先，有功就称病而不自夸，得以功名终。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "7adaa4e4-5502-54d6-b550-328f42c1bea7"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

