SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "荆南节度使成汭与其将许存溯江略地，取滨江州县。", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p021·原文件第102行", "note": "原文：荆南节度使成汭与其将许存溯江略地，尽取滨江州县。；核对说明：滨江是主书概括范围，不补未列州县或明确疆域边界。", "status": "draft", "id": "e368af67-b06d-5e79-9043-fd8bbd10b6fc", "subject_id": "4a832591-d400-5a79-afc6-298b59409581", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "896年五月条；确日未载", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p021·原文件第102行", "note": "原文：荆南节度使成汭与其将许存溯江略地，尽取滨江州县。；核对说明：滨江是主书概括范围，不补未列州县或明确疆域边界。", "status": "draft", "id": "b30e622f-9135-5292-9d2a-0929bddf01b5", "subject_id": "4a832591-d400-5a79-afc6-298b59409581", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记成汭：率部略地者。", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p021·原文件第102行", "note": "原文：荆南节度使成汭与其将许存溯江略地，尽取滨江州县。武泰节度使王建肇弃黔州，收馀众保丰都。存又引兵西取谕、涪二州，汭以其将赵武为黔中留后，存为万州刺史。汭知存不得志，使人诇之，曰：“存不治州事，日出蹴鞠。”汭曰：“存将逃，先匀足力也。”遣兵袭之，存弃城走；其众稍稍归之，屯于茅坝。赵武数攻丰都，王建肇不能守，与存皆降于王建，建忌存勇略，欲杀之，掌书记高烛曰：“公方总揽英雄以图霸业，彼穷来归我，奈向杀之！”建使戍蜀州，阴使知蜀州王宗绾察之。宗绾密言存忠勇廉厚，有良将才，建乃舍之，更其姓名臼王宗播，而宗绾竟不使宗播知其免己也。宗播元从也目官柳修业，每劝宗播慎静以免祸。其后宗播为建将，遇强敌诸将所惮者，以身先之。及有功，辄称病，不自伐，由是得以功名终。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "10b752b3-cb1d-5d6f-b935-7ce13964a4a8", "subject_id": "c476a6a9-2254-5cdf-b51d-55a7f49d0dd8", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "成汭：率部略地者。", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p021·原文件第102行", "note": "原文：荆南节度使成汭与其将许存溯江略地，尽取滨江州县。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "ba4aafdb-366b-5215-ab6d-202d44df39b6", "subject_id": "326137d4-a600-507c-9752-5db9ad85549d", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记许存：略地将。", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p021·原文件第102行", "note": "原文：荆南节度使成汭与其将许存溯江略地，尽取滨江州县。武泰节度使王建肇弃黔州，收馀众保丰都。存又引兵西取谕、涪二州，汭以其将赵武为黔中留后，存为万州刺史。汭知存不得志，使人诇之，曰：“存不治州事，日出蹴鞠。”汭曰：“存将逃，先匀足力也。”遣兵袭之，存弃城走；其众稍稍归之，屯于茅坝。赵武数攻丰都，王建肇不能守，与存皆降于王建，建忌存勇略，欲杀之，掌书记高烛曰：“公方总揽英雄以图霸业，彼穷来归我，奈向杀之！”建使戍蜀州，阴使知蜀州王宗绾察之。宗绾密言存忠勇廉厚，有良将才，建乃舍之，更其姓名臼王宗播，而宗绾竟不使宗播知其免己也。宗播元从也目官柳修业，每劝宗播慎静以免祸。其后宗播为建将，遇强敌诸将所惮者，以身先之。及有功，辄称病，不自伐，由是得以功名终。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "c9f61223-65d7-5535-8488-40972b8998c9", "subject_id": "e8b9aa84-3b89-5223-85a1-12c49d25bd5f", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "许存：略地将。", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p021·原文件第102行", "note": "原文：荆南节度使成汭与其将许存溯江略地，尽取滨江州县。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "18233041-3c7f-5228-a984-ff6a3231329b", "subject_id": "96f1e892-0653-58ff-bf6a-54fac99ddc76", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "event", "field_path": "description", "claim_text": "武泰节度使王建肇放弃黔州，收集余众，退保丰都。", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p021·原文件第102行", "note": "原文：武泰节度使王建肇弃黔州，收馀众保丰都。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "032bf4c0-e337-5707-a7fa-5d7dead31f92", "subject_id": "8a331f54-b3fc-5b98-be27-ef847e8ccc4f", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "896年成汭许存略地条；确日未载", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p021·原文件第102行", "note": "原文：武泰节度使王建肇弃黔州，收馀众保丰都。；核对说明：干支日未换算公历日。", "status": "draft", "id": "ebe113c0-08bf-505c-956a-444fa918dd54", "subject_id": "8a331f54-b3fc-5b98-be27-ef847e8ccc4f", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记王建肇：弃黔退保者。", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p021·原文件第102行", "note": "原文：荆南节度使成汭与其将许存溯江略地，尽取滨江州县。武泰节度使王建肇弃黔州，收馀众保丰都。存又引兵西取谕、涪二州，汭以其将赵武为黔中留后，存为万州刺史。汭知存不得志，使人诇之，曰：“存不治州事，日出蹴鞠。”汭曰：“存将逃，先匀足力也。”遣兵袭之，存弃城走；其众稍稍归之，屯于茅坝。赵武数攻丰都，王建肇不能守，与存皆降于王建，建忌存勇略，欲杀之，掌书记高烛曰：“公方总揽英雄以图霸业，彼穷来归我，奈向杀之！”建使戍蜀州，阴使知蜀州王宗绾察之。宗绾密言存忠勇廉厚，有良将才，建乃舍之，更其姓名臼王宗播，而宗绾竟不使宗播知其免己也。宗播元从也目官柳修业，每劝宗播慎静以免祸。其后宗播为建将，遇强敌诸将所惮者，以身先之。及有功，辄称病，不自伐，由是得以功名终。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "3c97b506-6df0-572c-952d-17dbcf92b126", "subject_id": "3a5543ae-4e1d-5d6f-8e87-4ae60879fe4f", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "王建肇：弃黔退保者。", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p021·原文件第102行", "note": "原文：武泰节度使王建肇弃黔州，收馀众保丰都。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "5b56a48f-f683-511c-ae0e-80f31efed047", "subject_id": "8c8e993c-e337-5602-a80e-dc160364306c", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "event", "field_path": "description", "claim_text": "许存又率兵向西，攻取底本所记“谕、涪二州”；“谕”与补书“渝”存在字形差异。", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p021·原文件第102行", "note": "原文：存又引兵西取谕、涪二州；核对说明：不静默改底本谕为渝；十国春秋卷35明确作渝涪，独立补证，不配现代坐标。", "status": "draft", "id": "99b87713-a0fb-557b-9506-0696dac17d6c", "subject_id": "f65adf15-a62a-5f39-9d66-8a0848def77e", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "896年溯江略地后条；确日未载", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p021·原文件第102行", "note": "原文：存又引兵西取谕、涪二州；核对说明：不静默改底本谕为渝；十国春秋卷35明确作渝涪，独立补证，不配现代坐标。", "status": "draft", "id": "483475bf-00f8-5233-82e9-3afda4f8c0bf", "subject_id": "f65adf15-a62a-5f39-9d66-8a0848def77e", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "许存：引兵西取者。", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p021·原文件第102行", "note": "原文：存又引兵西取谕、涪二州；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "2c5b19d9-e787-5be7-af5